```cpp
#include <iostream>
#include <string>
using namespace std;

class Book {
private:
    string title;
    string author;
    float price;

public:
    // Default Constructor
    Book() {
        title = "Unknown Title";
        author = "Unknown Author";
        price = 0.0;
    }

    // Parameterized Constructor
    Book(string t, string a, float p) {
        title = t;
        author = a;
        price = p;
    }

    // Copy Constructor
    Book(const Book &b) {
        title = b.title;
        author = b.author;
        price = b.price;
    }

    // Display function
    void display() const {
        cout << "Title: " << title << ", Author: " << author << ", Price: $" << price << endl;
    }
};

int main() {
    // Using Default Constructor
    Book b1;
    cout << "Book 1 (Default): ";
    b1.display();

    // Using Parameterized Constructor
    Book b2("C++ Programming", "Bjarne Stroustrup", 59.99);
    cout << "Book 2 (Parameterized): ";
    b2.display();

    // Using Copy Constructor
    Book b3 = b2;
    cout << "Book 3 (Copy of Book 2): ";
    b3.display();

    return 0;
}
```

Yes, this is an example of **Hierarchical Inheritance** because two derived classes (`Rectangle` and `Circle`) inherit from a single base class (`Shapes`).

