#include <iostream>
using namespace std;

class Shapes {
public:
    // Base class to provide a common interface if needed
};

class Rectangle : public Shapes {
private:
    float length, breadth;
public:
    void getdata() {
        cout << "Enter length and breadth for Rectangle: ";
        cin >> length >> breadth;
    }
    float area() {
        return length * breadth;
    }
    void printdata() {
        cout << "Area of Rectangle: " << area() << endl;
    }
};

class Circle : public Shapes {
private:
    float radius;
public:
    void getdata() {
        cout << "Enter radius for Circle: ";
        cin >> radius;
    }
    float area() {
        return 3.14159 * radius * radius;
    }
    void printdata() {
        cout << "Area of Circle: " << area() << endl;
    }
};

int main() {
    Rectangle rect;
    rect.getdata();
    rect.printdata();

    Circle circ;
    circ.getdata();
    circ.printdata();

    return 0;
}
