#include <iostream>
#include <string>
using namespace std;

template <class T>
class myFirstClass {
private:
    T num1, num2;
public:
    myFirstClass(T n1, T n2) : num1(n1), num2(n2) {}

    T getMin() {
        return (num1 < num2) ? num1 : num2;
    }

    T getMax() {
        return (num1 > num2) ? num1 : num2;
    }

    void display() {
        cout << "Min: " << getMin() << ", Max: " << getMax() << endl;
    }
};

int main() {
    // Integer
    myFirstClass<int> objInt(10, 20);
    cout << "Integer -> "; objInt.display();

    // Float
    myFirstClass<float> objFloat(15.5f, 10.2f);
    cout << "Float -> "; objFloat.display();

    // Double
    myFirstClass<double> objDouble(123.456, 789.012);
    cout << "Double -> "; objDouble.display();

    // String
    myFirstClass<string> objString("Apple", "Banana");
    cout << "String -> "; objString.display();

    return 0;
}
