    try {
        int choice;
        cout << "Enter 1 for Bound violation, 2 for Bad cast, 3 for Null pointer logic: ";
        cin >> choice;

        if (choice == 1) {
            // (ii) Bound violation using at() which throws out_of_range
            cout << "Accessing out of bounds: " << vect1.at(10) << endl;
        } 
        else if (choice == 2) {
            // (i) Type conversion/Bad cast simulation
            class Base { virtual void dummy() {} };
            class Derived : public Base { int a; };
            Base *b = new Base;
            Derived *d = dynamic_cast<Derived*>(b);
            if (d == nullptr) throw bad_cast();
        } 
        else if (choice == 3) {
            // (iii) Bad references / Null pointer simulation
            int* ptr = nullptr;
            if (!ptr) throw runtime_error("Null pointer exception");
            cout << *ptr;
        }
    } 
    catch (const out_of_range& e) {
        cout << "Exception caught: Bound violation - " << e.what() << endl;
    } 
    catch (const bad_cast& e) {
        cout << "Exception caught: Improper cast - " << e.what() << endl;
    } 
    catch (const runtime_error& e) {
