```cpp
#include <iostream>
#include <list>
using namespace std;

// User defined function to print list
void PrintList(const list<int>& lst, const string& msg) {
    cout << msg << ": ";
    for (int val : lst) {
        cout << val << " ";
    }
    cout << endl;
}

int main() {
    // Array of integer data type
    int arr[] = {40, 10, 30};
    int n = sizeof(arr) / sizeof(arr[0]);

    // Initialize list with array
    list<int> myList(arr, arr + n);
    PrintList(myList, "Initial List");

    // (i) Push_front()
    myList.push_front(50);
    PrintList(myList, "After push_front(50)");

    // (ii) insert() at beginning + 2
    auto it = myList.begin();
    advance(it, 2);
    myList.insert(it, 25);
    PrintList(myList, "After insert(25)");

    // (iii) sort()
    myList.sort();
    PrintList(myList, "After sort()");

    // Prepare second list for splice and merge
    list<int> list2 = {5, 15};

    // (iv) splice() - move all elements from list2 to beginning of myList
    myList.splice(myList.begin(), list2);
    PrintList(myList, "After splice(list2)");

    // (v) merge() - both lists must be sorted first
    list<int> list3 = {20, 35, 60};
    myList.sort(); // ensure sorted
    list3.sort();
    myList.merge(list3);
    PrintList(myList, "After merge(list3)");

    // (vi) pop_back()
    myList.pop_back();
    PrintList(myList, "After pop_back()");

    return 0;
}
```

```cpp
#include <iostream>
#include <queue>
#include <map>
using namespace std;

int main() {
    cout << "--- STL Queue Operations ---\n";
    queue<int> q;
    // (i) Insert
    q.push(10); q.push(20); q.push(30);
    cout << "Queue after insertion: ";
    // (iii) Display (Queue doesn't have iterators, must copy/pop to display)
    queue<int> qCopy = q;
    while(!qCopy.empty()) { cout << qCopy.front() << " "; qCopy.pop(); }
    cout << endl;
    // (ii) Delete
    q.pop();
    cout << "Queue after deletion (pop front): ";
    qCopy = q;
    while(!qCopy.empty()) { cout << qCopy.front() << " "; qCopy.pop(); }
    cout << "\nQueue has no built-in find method (linear search needed).\n\n";

    cout << "--- STL Map Operations ---\n";
    map<int, string> m;
    // (i) Insert
    m.insert({1, "Apple"});
    m[2] = "Banana";
    m[3] = "Cherry";
    // (iii) Display
    cout << "Map contents:\n";
    for(auto const& pair : m) {
        cout << pair.first << ": " << pair.second << endl;
    }
    // (iv) Find
    auto it = m.find(2);
    if(it != m.end()) cout << "Found key 2: " << it->second << endl;
    else cout << "Key 2 not found.\n";
    // (ii) Delete
    m.erase(2);
    cout << "Map after deleting key 2:\n";
    for(auto const& pair : m) {
        cout << pair.first << ": " << pair.second << endl;
    }

    return 0;
}
```

**Method Overloading** is a feature in C++ where multiple functions can have the same name but different parameters (number, type, or both). The compiler determines which function to execute based on the arguments passed during the function call.

*Note: C++ does NOT allow function overloading based solely on the return type. Therefore, condition (ii) "Same number of arguments with different return types" is strictly impossible in standard C++ overloading rules. To fulfill the intent, we can use different argument types (e.g., `int` vs `double`) along with different return types.*

```cpp
#include <iostream>
#include <cmath>
using namespace std;

// (i) Different number of arguments with same return type
// Volume of a Cube: V = a^3 (1 argument)
double calculateVolume(double side) {
    return side * side * side;
}

// Volume of a Cylinder: V = pi * r^2 * h (2 arguments)
double calculateVolume(double radius, double height) {
    return 3.14159 * radius * radius * height;
}

// (ii) Different argument types (needed for overloading) and different return types
// Volume of a Sphere: V = (4/3) * pi * r^3 
// Taking an integer radius and returning a float to demonstrate different types.
float calculateVolume(int radius) {
    return (4.0f / 3.0f) * 3.14159f * radius * radius * radius;
}

int main() {
    double cubeSide = 5.0;
    double cylRadius = 3.0, cylHeight = 7.0;
    int sphereRadius = 4;

    cout << "Volume of Cube (side 5.0): " 
         << calculateVolume(cubeSide) << endl; // Calls 1-arg double version

    cout << "Volume of Cylinder (radius 3.0, height 7.0): " 
         << calculateVolume(cylRadius, cylHeight) << endl; // Calls 2-arg version

    cout << "Volume of Sphere (radius 4): " 
         << calculateVolume(sphereRadius) << endl; // Calls 1-arg int version

    return 0;
}
```

```cpp
#include <iostream>
using namespace std;

// Base class
class Shape {
public:
    void print() {
        cout << "This is a shape" << endl;
    }
};

// Polygon inherits from Shape (Single Inheritance)
class Polygon : public Shape {
public:
    void print() {
        cout << "Polygon is a shape" << endl;
    }
};

// Rectangle inherits from Polygon (Multilevel Inheritance)
class Rectangle : public Polygon {
public:
    void print() {
        cout << "Rectangle is a polygon" << endl;
    }
};

// Triangle inherits from Polygon (Hierarchical Inheritance from Polygon)
class Triangle : public Polygon {
public:
    void print() {
        cout << "Triangle is a polygon" << endl;
    }
};

// Square inherits from Rectangle (Multilevel Inheritance)
class Square : public Rectangle {
public:
    void print() {
        cout << "Square is a rectangle" << endl;
    }
};

int main() {
    // Creating objects of each class
    Shape s;
    Polygon p;
    Rectangle r;
    Triangle t;
    Square sq;

    // Calling the print function for each object
    // This demonstrates function overriding/hiding
    cout << "Calling print from Shape object: ";
    s.print();

    cout << "Calling print from Polygon object: ";
    p.print();

    cout << "Calling print from Rectangle object: ";
    r.print();

    cout << "Calling print from Triangle object: ";
    t.print();

    cout << "Calling print from Square object: ";
    sq.print();

    return 0;
}
```
